import{_ as e,o as t,c as i,a}from"./app.83c7065c.js";const f=JSON.parse('{"title":"web性能优化指标解析","description":"","frontmatter":{"title":"web性能优化指标解析","date":"2020-04-12"},"headers":[],"relativePath":"2020/web-performance-metrics.md","lastUpdated":1786184870000}'),n={name:"2020/web-performance-metrics.md"},l=a('<h3 id="写在前面" tabindex="-1">写在前面 <a class="header-anchor" href="#写在前面" aria-hidden="true">#</a></h3><p>1.sequence</p><p>request - server responds - domContentLoaded - load</p><ol start="2"><li>Choose the metrics</li></ol><p>web.dev/user-centric-performance-metrics</p><p>2.1 Is there content?</p><ul><li><p>Time to First Byte</p><p>a) Time from when the browser requests a page to the first bye of the page being received</p><p>b) Value = time to establish connection + 2*time to transmission + time for server respond</p></li><li><p>First Paint</p><p>a) time when the first pixel is painted on the screen</p><p>b) value greater than TTFB, somewhere after domContentLoaded</p></li><li><p>First Contentful Paint</p><p>a) time when the first piece of content from the DOM is rendered</p><p>b)</p></li></ul><p>2.2 is the content meaningful?</p><ul><li><p>Largest Contentful Paint</p><p>a) successor to FMP, measures the time when the largest piece fo content whithin the viewport is rendered</p><p>b) better than FMP</p></li><li><p>Visually Complete</p><p>a) time taken for the content within the viewport to be fully rendered</p><p>b) longer than LCP</p></li><li><p>Speed Index</p><p>a) score of how quickly visual content is rendered within the viewport</p><p>b)</p></li></ul><p>2.3 is the content interactable?</p><ul><li><p>First Input Delay</p><p>a) delay between the time a user can attempt to interact with a part fo the site, and the time that the interface is able to respond to that interaction</p></li><li><p>Max Potential First Input Delay</p><p>a) maximum possible First Input Delay based on the duration of the longest task</p></li><li><p>Total Blocking Time</p><p>a) total duration of JavaScript tasks between the First Contentful Paint and Time to Interactive</p></li><li><p>Time to Interactive</p><p>a) time when the. main thread has had up to 5sec with no network activitiy or JavaScript tasks</p></li></ul><p>2.4 Are interactions smooth?</p><ul><li><p>Cumulative Layout Shift</p><p>a) shifts in layout while a page is loading</p></li><li><p>Frame Rate</p><p>a) rate at which the browser can produce new frames in response to interactions and/or animations</p></li></ul><p>2.5 Example</p><p>e.g. News Website</p><ul><li>is there content? First Contentful Paint</li><li>is the content meaningful? Largest Contentful Paint, Speed Index</li><li>is the content intractable? Time to Interactive</li><li>Are the interactions smooth? Cumulative Layout Shift</li></ul><ol start="3"><li>Define a budget</li></ol><ul><li>a performance budget defines specific values to your metrics that your site should never exceed.</li></ul><p>e.g. News Website</p><ul><li>FCP &lt; 1.5s</li><li>LCP &lt; 2s</li><li>SI &lt; 0.43</li><li>TTI &lt; 4s</li><li>CLS&lt;0.1</li></ul><p>OR use competitors as a guide/baseline</p><ol start="4"><li>Start measuring</li></ol><ul><li>Lighthouse</li><li>Calibre</li></ul>',23),o=[l];function r(s,p,c,h,u,d){return t(),i("div",null,o)}const b=e(n,[["render",r]]);export{f as __pageData,b as default};
